nueva('hygrophoropsis-aurantiaca', cient='Hygrophoropsis aurantiaca', sin=['Agaricus aurantiacus', 'Cantharellus aurantiacus'], es=['falso rebezuelo', 'rebezuelo anaranjado'], eu=['zizahori faltsu', 'zizahori faltsua'], grupo='laminar', clase='no_comestible', cand=False,
  nota='Wikipedia en inglés la da como venenosa (puede causar problemas digestivos serios); hasta 1999 se describía a veces como comestible poco sabrosa; la Wikipedia en euskera la da como comestible muy inferior al rebozuelo. Con fuentes en desacuerdo, aquí se trata como no comestible.',
  clave='«Falso rebozuelo»: sombrero naranja dorado con pelusa fina y estructuras como láminas estrechas, bifurcadas y de un naranja más intenso que el sombrero. El rebozuelo tiene pliegues romos.',
  mirar=[q('sombrero', 'Naranja dorado con fina pelusa', '2–10 cm; convexo y luego en embudo. El borde queda algo enrollado y se ondula o lobula con la edad. Cubierto de una pelusa fina.'),
         q('himenio', 'Láminas estrechas y bifurcadas', 'Estructuras decurrentes como láminas, estrechas y bifurcadas, de un naranja más intenso que el sombrero; pueden estar algo onduladas junto al pie. Es el rasgo distintivo.'),
         q('pie', 'Naranja, sin anillo', '1,5–8 cm de alto y 0,5–1 cm de grosor; base a menudo más oscura, parda.'),
         q('carne', 'Blanda y fina', 'De blanca a amarillenta o naranja dorado; olor y sabor poco definidos o desagradables y terrosos.'),
         q('esporada', 'Esporada blanca a crema', 'Blanca a crema.'),
         q('habitat', 'Bosques y brezales', 'Bosques de frondosas y coníferas y brezales, en verano y otoño. Saprótrofa del mantillo y de madera descompuesta.')],
  conf=[c('cantharellus-cibarius', 'Cantharellus cibarius (rebozuelo)', 'El rebozuelo tiene pliegues romos, como arrugas, y el falso rebozuelo estructuras estrechas como láminas, más anaranjadas que el sombrero. El catálogo inicial indica que el criterio diferenciador está por contrastar con una guía.', 'media'),
        c('omphalotus-illudens', 'Omphalotus', 'David Arora especuló que a veces se tomó por comestible por confundirse con Omphalotus, que es tóxico.', 'media')],
  hab=['frondosas', 'coniferas', 'brezal'], habt='Bosques de frondosas y coníferas y brezales de Europa y América. Saprótrofa: se alimenta de hojarasca y madera en descomposición, a la que produce podredumbre parda.',
  rec=dict(acc='dejar', txt='No se coge. Se parece al rebozuelo y las fuentes no se ponen de acuerdo sobre su comestibilidad.'),
  sind='Puede causar problemas digestivos serios. Contiene niveles altos de arabitol.', lat=None, grav=None,
  cur=['Hasta 1999 a veces se describía como comestible (aunque poco sabrosa). Fries ya la llamó «venenatus» en 1821.',
       'Franz Xaver von Wulfen la describió en 1781 como Agaricus aurantiacus.',
       'Segrega mucho ácido oxálico, que ayuda a deshacer el humus del suelo del bosque.'],
  meses=[6, 7, 8, 9, 10, 11], mnota='Verano y otoño.', wp=['hygrophoropsis-aurantiaca'], rioja=False)

nueva('trametes-versicolor', cient='Trametes versicolor', sin=['Coriolus versicolor', 'Polyporus versicolor'], es=[], eu=['larruki koloreanitz', 'larruki koloreanitza'], grupo='poliporo', clase='no_comestible', cand=False,
  clave='Repisas finas, duras y flexibles, con anillos concéntricos de varios colores, en tejas sobre troncos y tocones. Poros diminutos blanquecinos. Demasiado duro para comer.',
  mirar=[q('sombrero', 'Semicircular, fino y duro', 'Sin pie. Plano, de hasta 10 cm de ancho; carne dura de 1–3 mm de grosor. Suele ser triangular o redondo, y crece en capas solapadas.'),
         q('cutis', 'Zonas concéntricas de colores', 'Zonas de finos pelitos de color pardo-óxido o pardo más oscuro, a veces con zonas negras. Los ejemplares viejos pueden llevar algas verdes.'),
         q('himenio', 'Poros blanquecinos, muy finos', 'La cara inferior tiene zonas concéntricas de distinto color, con el margen siempre más claro. Poros blanquecinos a pardo claro (3–5 por mm), redondos y con la edad retorcidos.'),
         q('habitat', 'Troncos y tocones de frondosas', 'En capas como tejas, en grupos o filas, sobre troncos y tocones de frondosas.')],
  conf=[c(None, 'Stereum ostrea (falsa cola de pavo)', 'Parecida a simple vista. Los Stereum suelen tener la cara inferior lisa, sin poros.', 'baja'),
        c(None, 'Otros hongos de repisa', 'También se parece a Trametes betulina, T. hirsuta, T. ochracea, Bjerkandera adusta y Lenzites betulina (Wikipedia).', 'baja')],
  hab=['frondosas', 'madera'], habt='Muy común en el mundo entero, en troncos y tocones de frondosas, en tejas, en grupos o filas. Es un hongo de podredumbre blanca que degrada la lignina de la madera.',
  rec=dict(acc='dejar', txt='No se recoge para comer: Wikipedia la considera demasiado dura.'),
  cur=['«versicolor» significa «de varios colores». Sus zonas concéntricas se parecen a las del plumaje de un pavo, de ahí su nombre inglés «turkey tail» (cola de pavo).',
       'En China se consume desde hace miles de años como té o polvo con el nombre «yunzhi» y se usa en medicina tradicional.',
       'Las orugas de una polilla (Nemaxera betulinella) y larvas de algunas moscas se la comen.'],
  meses=[], mnota=None, wp=['trametes-versicolor'], rioja=False)

nueva('fomes-fomentarius', cient='Fomes fomentarius', sin=['Polyporus fomentarius'], es=['hongo yesca', 'hongo yesquero', 'hongo pata de caballo'], eu=['supizteko ardagai', 'sultzo', 'ardagai gorri', 'karduba'], grupo='poliporo', clase='no_comestible', cand=False,
  clave='Hongo en forma de pezuña de caballo, duro como la madera y gris o pardo con crestas concéntricas, pegado al tronco. Poros crema que oscurecen al tocarlos. Era la yesca para hacer fuego; no se come.',
  mirar=[q('sombrero', 'Forma de pezuña, duro y leñoso', 'Entre 5 y 45 cm de ancho. Normalmente en forma de casco de caballo, o más bien como repisa; con crestas anchas concéntricas y el margen romo y redondeado.'),
         q('cutis', 'Gris o pardo claro, con corteza dura', 'Superficie dura, bultosa y leñosa, gris o pardo claro; el margen es blanquecino mientras crece. Corteza dura de 1 a 2 mm.'),
         q('himenio', 'Poros crema que oscurecen', 'Poros redondos, crema al principio y pardos al madurar, y se oscurecen cuando se tocan; 2–3 por mm.'),
         q('carne', 'Dura, fibrosa, color canela', 'Dura y fibrosa, de color pardo canela. Sabor acre.'),
         q('habitat', 'En troncos de frondosas', 'Pegado al tronco de frondosas; entra por corteza dañada. Es un hongo de podredumbre blanca.')],
  conf=[],
  hab=['frondosas', 'arbol_vivo', 'madera'], habt='Muy extendido en el hemisferio norte, África, Asia y Europa. Se asocia al tronco de frondosas y produce una podredumbre blanca que deja la madera pálida y fibrosa.',
  rec=dict(acc='dejar', txt='No se recoge para comer: es inedible.'),
  cur=['Se usaba para hacer «amadou», una yesca para encender fuego. Hace unos 5 000 años, Ötzi, el hombre de hielo, llevaba cuatro trozos, aparentemente para hacer fuego.',
       'En medicina antigua se usó como hemostático (para cortar hemorragias) según la Wikipedia en euskera.',
       'Infecta a los árboles por la corteza dañada y reduce el valor de la madera.',
       'Linneo la describió en 1753 en «Species Plantarum».'],
  meses=[], mnota=None, wp=['fomes-fomentarius'], rioja=False)

nueva('inocybe-erubescens', cient='Inosperma erubescens', sin=['Inocybe erubescens', 'Inocybe patouillardii'], es=[], eu=['inozibe hiltzaile', 'inozibe hiltzailea'], grupo='laminar', clase='mortal', cand=False,
  nomen='Antes se llamaba Inocybe erubescens o I. patouillardii; hoy Inosperma erubescens.',
  clave='Seta pálida de primavera y verano que se mancha de ROJO al tocarla o con la edad, de láminas rosa-rojizas; se parece al perrechico (Calocybe gambosa). Contiene muscarina, potencialmente mortal.',
  mirar=[q('sombrero', 'Blanco que amarillea y se mancha de rojo', 'Hasta 8 cm; hemisférico y luego aplanado. Blanco al principio, luego amarillo o pardusco, con marcas y líneas rosa-blanquecinas y rojas. El borde, a menudo irregular, con grietas y textura áspera.'),
         q('himenio', 'Láminas rosa-rojizas', 'Adnexas (unidas por una pequeña parte) y de color rosa-rojizo.'),
         q('pie', 'Rojo-rosado oscuro, sin anillo', 'Delgado, de un rosa rojizo oscuro y sin anillo.'),
         q('carne', 'Amarillenta, luego rosa oscuro', 'Amarillenta al principio y después rosa oscuro. El color tiende a desvanecerse con luz solar directa.'),
         q('habitat', 'Hayedos y suelos calizos, en primavera-verano', 'Sobre todo en hayedos y suelos calizos, también en otros bosques de frondosas, entre la hojarasca; principalmente en primavera y verano.')],
  conf=[c('calocybe-gambosa', 'Calocybe gambosa (perrechico)', 'Se puede tomar por el perrechico, pero este NO se mancha de rojo. Aparecen en la misma época, así que no hay que fiarse solo de la época.', 'alta'),
        c(None, 'Agaricus y Cortinarius caperatus', 'Wikipedia también la cita como posible confusión con algunos Agaricus y con Cortinarius caperatus.', 'media')],
  hab=['hayedo', 'frondosas'], habt='Sobre todo hayedos y suelos calizos, pero también en otros bosques de frondosas. Crece sobre la hojarasca, normalmente en primavera y verano. Se encuentra en el sur de Europa.',
  rec=dict(acc='dejar', txt='No se coge. Si recoges perrechicos, comprueba cada ejemplar: ninguna debe ponerse roja al tocarla.'),
  sind='Síndrome muscarínico, causado por la muscarina. Dosis potencialmente mortal; se registró una muerte en Surrey (Inglaterra) en 1937. Requiere atención médica urgente.', lat=None, grav='Potencialmente mortal',
  cur=['La describió el naturalista noruego Axel Blytt en 1904.',
       'En Israel se confunde con setas comestibles del género Tricholoma, como T. terreum.',
       'El color rojo es tan característico que da nombre a la especie: «erubescens» significa «que se pone rojo».'],
  meses=[3, 4, 5, 6, 7, 8], mnota='Principalmente en primavera y verano.', wp=['inocybe-erubescens'], rioja=False)
